import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { SAMPLE_VIDEO } from '../data';

export default function Signup() {
  const navigate = useNavigate();
  const [role, setRole] = useState('student');
  const [form, setForm] = useState({ name: '', email: '', password: '', age: '' });
  const [error, setError] = useState('');

  const handleChange = e =>
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));

  async function handleSubmit(e) {
    e.preventDefault();
    setError('');

    try {
      // 🔗 Keep backend API connection unchanged
      const res = await fetch('http://localhost:5000/api/auth/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, role }),
      });

      const data = await res.json();

      if (res.ok) {
        navigate('/login');
      } else {
        setError(data.message || 'Signup failed');
      }
    } catch (err) {
      console.error('Signup error:', err);
      setError('Something went wrong. Please try again.');
    }
  }

  const isStudent = role === 'student';
  const bgColor = isStudent ? '#e3f2fd' : '#e8f5e9';
  const themeColor = isStudent ? '#1976d2' : '#2e7d32';

  return (
    <div
      className="auth-page"
      style={{
        background: bgColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <div
        className="auth-card"
        style={{
          background: 'white',
          borderRadius: '16px',
          padding: '40px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
          width: '400px',
        }}
      >
        <h1 style={{ color: themeColor, textAlign: 'center' }}>Join Nexora</h1>

        <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', margin: '12px 0' }}>
          <button
            onClick={() => setRole('student')}
            style={{
              background: isStudent ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '6px 12px',
              cursor: 'pointer',
            }}
          >
            Student
          </button>
          <button
            onClick={() => setRole('staff')}
            style={{
              background: !isStudent ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '6px 12px',
              cursor: 'pointer',
            }}
          >
            Staff
          </button>
        </div>

        <form className="form" onSubmit={handleSubmit}>
          <input
            className="input"
            name="name"
            placeholder="Full Name"
            value={form.name}
            onChange={handleChange}
            required
          />
          {isStudent && (
            <input
              className="input"
              name="age"
              type="number"
              placeholder="Age"
              value={form.age}
              onChange={handleChange}
              required
            />
          )}
          <input
            className="input"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            required
          />
          <input
            className="input"
            name="password"
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            required
          />
          <button
            className="btn btn-primary"
            type="submit"
            style={{
              background: themeColor,
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '10px',
              width: '100%',
              marginTop: '10px',
              cursor: 'pointer',
            }}
          >
            Sign Up
          </button>
          {error && (
            <p style={{ color: 'red', marginTop: '8px' }}>{error}</p>
          )}
          <div style={{ marginTop: 12, textAlign: 'center' }}>
            <span>Already have an account? </span>
            <Link to="/login" style={{ color: themeColor }}>
              Login
            </Link>
          </div>
        </form>
      </div>
    </div>
  );
}
